import { WORD_LENGTH } from "./engine";

let guessList: ReadonlySet<string> | null = null;
let guessLoad: Promise<ReadonlySet<string>> | null = null;

/**
 * Load the guess list: every six-letter word in ENABLE, SCOWL-70 or the
 * answer list (`guesses/6.ts`, generated by scripts/generate-guesses.ts),
 * fetched as its own chunk the first time the game opens.
 */
export function loadGuessList(): Promise<ReadonlySet<string>> {
  if (guessLoad) {
    return guessLoad;
  }
  guessLoad = import(`./guesses/${WORD_LENGTH}.ts`)
    .then((module: { default: string }) => {
      guessList = new Set(module.default.split(" "));
      return guessList;
    })
    .catch((error: unknown) => {
      guessLoad = null;
      throw error;
    });
  return guessLoad;
}

/**
 * A guess counts when the loaded guess list has it or it is the day's
 * answer. The view awaits the list before play; without it only the answer
 * passes, so a missing chunk narrows the game and never breaks it.
 */
export function isAllowedGuess(word: string, answer: string): boolean {
  const normalized = word.toLowerCase();
  return (
    normalized === answer.toLowerCase()
    || (guessList?.has(normalized) ?? false)
  );
}
